                    ("fx", "grad_pair", r"\hat{y}=\operatorname{softmax}(x):\qquad \frac{\partial\,\mathrm{CE}}{\partial x_k}=s_k-y_k"),
                    ("p", "example", {"ru": "Логиты $(2;\\,1;\\,0)$, правильный класс — первый. $s\\approx(0{,}665;\\,0{,}245;\\,0{,}090)$, $\\mathrm{CE}=-\\ln0{,}665\\approx0{,}408$, градиент $s-y\\approx(-0{,}335;\\,0{,}245;\\,0{,}090)$: правильный логит тянется вверх, остальные — вниз.",
                                      "en": "Logits $(2,\\,1,\\,0)$, the correct class is the first. $s\\approx(0.665,\\,0.245,\\,0.090)$, $\\mathrm{CE}=-\\ln0.665\\approx0.408$, gradient $s-y\\approx(-0.335,\\,0.245,\\,0.090)$: the correct logit is pulled up and the others down.",
                                      "uz": "$(2;\\,1;\\,0)$ logitlar, to‘g‘ri sinf — birinchisi. $s\\approx(0{,}665;\\,0{,}245;\\,0{,}090)$, $\\mathrm{CE}=-\\ln0{,}665\\approx0{,}408$, gradiyent $s-y\\approx(-0{,}335;\\,0{,}245;\\,0{,}090)$: to‘g‘ri logit yuqoriga, qolganlari pastga tortiladi."}),
                    ("code", "code", "def cross_entropy(logits, k):\n    z = logits - logits.max()\n    return np.log(np.exp(z).sum()) - z[k]"),
